import{_ as t,a,o as n,a4 as s}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Delete Admin User","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql","title":"Delete Admin User","query":"mutation DeleteAdminSettingsUser($input: deleteAdminSettingsUserInput!) {\\n  deleteAdminSettingsUser(input: $input) {\\n    adminSettingsUser {\\n      _id\\n      name\\n      email\\n      roleId\\n      roleName\\n      status\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/settings/users/3167\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminSettingsUser\\": {\\n      \\"adminSettingsUser\\": {\\n        \\"_id\\": 3167,\\n        \\"name\\": \\"Throwaway Delete Test\\",\\n        \\"email\\": \\"throwaway-deltest-9921@example.com\\",\\n        \\"roleId\\": 15,\\n        \\"roleName\\": \\"DebugAdmin\\",\\n        \\"status\\": 1,\\n        \\"message\\": \\"Admin user deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/users/delete.md","filePath":"api/graphql-api/admin/settings/users/delete.md","lastUpdated":1783420618000}'),o={name:"api/graphql-api/admin/settings/users/delete.md"};function d(i,e,r,l,c,u){return n(),a("div",null,e[0]||(e[0]=[s('<h1 id="delete-admin-user" tabindex="-1">Delete Admin User <a class="header-anchor" href="#delete-admin-user" aria-label="Permalink to &quot;Delete Admin User&quot;">​</a></h1><p>Deletes another admin user by id. The mutation returns a snapshot of the deleted record, so you can read back its <code>_id</code>, <code>name</code>, <code>email</code>, <code>roleId</code>, <code>roleName</code>, and <code>status</code> in the same response. The <code>password</code> and <code>api_token</code> values are never returned.</p><div class="warning custom-block"><p class="custom-block-title">Delete guards</p><ul><li><strong>Cannot delete yourself</strong> through this endpoint — the id must belong to a different admin. To remove your own account use <a href="./delete-self.html">Delete My Account</a>.</li><li><strong>Cannot delete the last remaining admin.</strong></li></ul><p>A blocked delete returns the reason in the <code>errors</code> array and leaves the account intact.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminSettingsUser(input:)</code></td><td>Mutation</td><td>Delete an admin user</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The returned node is an in-memory snapshot of the just-deleted record — its scalar fields (<code>_id</code>, <code>name</code>, <code>email</code>, <code>roleId</code>, <code>roleName</code>, <code>status</code>) still resolve so you can confirm what was removed.</li><li>Select <strong><code>message</code></strong> for the success confirmation — it resolves to <code>&quot;Admin user deleted successfully.&quot;</code> on a successful delete. <code>message</code> is <code>null</code> on read / list / create / update; a blocked delete returns a top-level <code>errors[]</code> entry instead.</li><li>Do <strong>not</strong> select the node&#39;s IRI <code>id</code> field on this mutation — the IRI cannot be generated for a deleted record and the field resolves with an <code>errors[]</code> entry. Select <code>_id</code> instead, as shown.</li><li>Use the <a href="./list.html"><code>adminSettingsUsers</code></a> query to discover valid ids.</li></ul><div class="tip custom-block"><p class="custom-block-title">Overview</p><p>For field meanings and create/update rules, see the <a href="./">Users overview</a>.</p></div><p>Requires the <code>settings.users.users.delete</code> permission and an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',9)]))}const p=t(o,[["render",d]]);export{h as __pageData,p as default};
